import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/README.md","filePath":"zh/root/README.md"}'),r={name:"zh/root/README.md"};function o(d,e,l,i,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<div align="center"><h1 id="open-cube-os" tabindex="-1">Open Cube OS <a class="header-anchor" href="#open-cube-os" aria-label="Permalink to &quot;Open Cube OS&quot;">​</a></h1><p><strong>一个从零写起的 x86_64 内核，附带 WinRE 风格的恢复 Shell。</strong></p><p>当前发布：<strong>v2.2.0</strong> —— 修复批次：以真实的内核根因修复（不改测试套件、 不做超时包装）关闭 2.1.0 的全部两项遗留——wp10_tui 套件末尾的内核栈 <strong>#DF</strong>（<code>checkupdate</code> HTTPS x509/RSA 最深真实调用链超出 6 页 kthread 栈、侵入守卫页——栈扩至 10 页并记录实测最深链）、<strong>wait4-vs-fork</strong> flake（tid 复用后收集到陈旧僵尸——孤儿脱钩记账修复，20/20 次 fresh boot 验证）。另：2.0.0 镜像资产补回、发布构建号三处口径完全一致（见 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">Releases</a>）。</p><p><code>oc&gt;</code> 是回退提示符，<code>ush&gt;</code> 是默认提示符。一切皆可扩展。</p><p><a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">官网</a> · <a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">文档</a> · <a href="https://cubestudio-dev.github.io/OpenCubeOS/#downloads" target="_blank" rel="noreferrer">下载</a> · <a href="./BUILDING.html">构建</a> · <a href="./ARCHITECTURE.html">架构</a> · <a href="./INTERFACES.html">接口参考</a></p></div><hr><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>Open Cube OS 是 <strong>L0 + L1</strong>：一个完整的、自包含的 64 位内核，可在 真实硬件和 QEMU 中启动，拉起默认的 Ring-3 应用（ush 用户 Shell， 横跨 L0 恢复 Shell 与 L1 服务面的 <strong>251 条命令</strong>），并在 Ring-3 世界 无法启动时回退到恢复 Shell 提示符（<code>oc&gt;</code>）。</p><ul><li><strong>不是 Linux 分支。</strong> Apache 2.0 下的 130,572 行原创 C/汇编 （验证：见下文 <em>Stats</em>）。</li><li><strong>PC 平台能启动的地方都能启动：</strong> BIOS + UEFI 混合 ISO，512 MiB 内存即可舒适运行，磁盘可选。</li><li><strong>一个真正的内核：</strong> 抢占式调度器、4 级分页、带 54 个系统调用的 Ring-3 用户程序、FAT32/exFAT/ext4/ramfs 上的 VFS、包含 TLS 1.2/1.3 和 SSH（客户端 <em>与</em> 服务器）的完整 TCP/IP 协议栈、从 NVMe 到 xHCI 再到 ACPI AML 的 16 个驱动家族、崩溃转储、硬件看门狗 （Intel TCO / ACPI WDAT）、OTA A/B 更新。</li><li><strong>设计即恢复环境：</strong> 系统<em>本身</em>就是 WinRE 式环境——启动、诊断、 修复、安装、更新。</li></ul><p>两层架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  Open Cube OS        内核 + oc&gt; 恢复 Shell                &lt;- 本仓库</span></span>
<span class="line"><span>L1  Ring-3 服务        17 个 SYS_L1SVC 类别 / 158 个操作 + ush</span></span></code></pre></div><p>2.0.0 起 L1 侧就在树内：<code>l1apps/</code> 收纳 Ring-3 应用（ush——默认启动 项，加上 ld.so 与动态链接测试程序），每个操作性命令类都移到了 SYS_L1SVC 服务面之后 （<a href="./INTERFACES.html">INTERFACES.md</a>——v1→v2 映射表就是兼容性契约； 2.1.0 将其补全到全部 233 条基线命令，零遗漏）。</p><h2 id="亮点" tabindex="-1">亮点 <a class="header-anchor" href="#亮点" aria-label="Permalink to &quot;亮点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>你能得到什么</th></tr></thead><tbody><tr><td>启动</td><td>GRUB 2.12 混合 ISO（BIOS El Torito + UEFI 映像）、multiboot2 附带 <code>self</code> 内核模块、A/B 槽位菜单</td></tr><tr><td>内存</td><td>基于 multiboot2 内存图的 PMM 位图、4 级 VMM、经 #PF 真实增长的 kmalloc 堆</td></tr><tr><td>CPU</td><td>抢占式优先级 + 轮转调度器、带 IST 栈的 256 门 IDT、100 Hz PIT + HPET/PM-timer/TSC 时间源、LAPIC</td></tr><tr><td>Ring 3</td><td>ELF 加载器、54 个系统调用、信号、fork/exec/pipes/select/mmap、动态链接（树内 ld.so、PIE、dlsym）；SYS_L1SVC + SYS_NETCMD 服务桥</td></tr><tr><td>存储</td><td>AHCI、ATA/ATA-DMA、NVMe、virtio-blk、USB MSC、SCSI（LSI）；支持 LFN 的 FAT32、exFAT、ext4、ramfs；GPT/MBR 分区；A/B 槽位</td></tr><tr><td>网络</td><td>e1000/e1000e/igb/ixgbe/rtl8139/rtl8169 家族/BCM57xx 驱动、ARP/IPv4/ICMP/UDP/DNS/TCP（含拥塞控制）、套接字、防火墙、HTTPS 客户端（TLS 1.2/1.3 + X.509 链）、SSH 客户端 + sshd</td></tr><tr><td>USB</td><td>UHCI、OHCI、EHCI、xHCI；大容量存储、HID、串口、音频类</td></tr><tr><td>媒体</td><td>HDA / AC97 / SB16 / ES1370 / virtio 声音；MJPEG 的 UVC 摄像头</td></tr><tr><td>平台</td><td>ACPI（FADT/DSDT/MCFG、真实 AML 遍历器、S3 挂起/恢复）、Intel TCO + ACPI WDAT 硬件看门狗、HPET、i2c/SMBus</td></tr><tr><td>Shell</td><td>ush（Ring 3，默认启动项）：133 条服务命令 + 内建（管道/重定向/通配符/环境变量/别名/作业）；oc&gt; 恢复 Shell：99 条命令</td></tr><tr><td>TUI</td><td>桌面、任务栏、菜单、表单、编辑器、系统应用——外加中文控制台层（16x16 字体、拼音输入法）</td></tr><tr><td>可靠性</td><td>崩溃转储到串口 + /etc crashlog、带轮转/级别/过滤的内核日志、健康监视（CPU/内存/任务/IO + JSON 导出）、SHA256 + 签名验证并带回滚的 OTA</td></tr></tbody></table><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 构建（Linux）：需要 gcc nasm xorriso mtools grub-common</span></span>
<span class="line"><span>#               grub-pc-bin grub-efi-amd64-bin zip python3</span></span>
<span class="line"><span>./build.sh iso</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 运行</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 访客内部（默认启动项是 Ring-3 的 ush Shell）</span></span>
<span class="line"><span>ush&gt; help</span></span>
<span class="line"><span>ush&gt; dhcp</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; wget 10.0.2.2</span></span>
<span class="line"><span>ush&gt; uname -a</span></span>
<span class="line"><span>ush&gt; exit          # -&gt; 落入 oc&gt; 恢复 Shell（99 条命令）</span></span></code></pre></div><p>UEFI 而非 BIOS：<code>make run-uefi</code>。Windows 宿主：<code>build.ps1</code> （WSL2/MSYS2）。完整指南：<a href="./BUILDING.html">BUILDING.md</a>。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>每个发布都从同一字节可复现流水线产出三份资产——当前发布永远在 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub releases 页</a> 并镜像于<a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">官网下载页</a>：</p><table tabindex="0"><thead><tr><th>资产</th><th>它是什么</th></tr></thead><tbody><tr><td><code>opencube-2.2.0.iso</code></td><td>BIOS+UEFI 混合可启动 ISO——QEMU 启动或写入 U 盘</td></tr><tr><td><code>opencube-2.2.0-src.zip</code></td><td>确定性源码 zip（<code>git archive</code>）</td></tr><tr><td><code>opencube-2.2.0-update.tar.gz</code></td><td>OTA 更新包（SHA256 + 签名验证，A/B 槽位）</td></tr></tbody></table><p>每份发布说明附全部三个 SHA256；官网、Release 与私密镜像持有字节 一致的副本。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li><a href="./BUILDING.html">BUILDING.md</a> - Linux/Windows 构建、QEMU、交叉编译 （ARM64/RISC-V Shell）、可复现验证</li><li><a href="./ARCHITECTURE.html">ARCHITECTURE.md</a> - L0 架构，自顶向下</li><li><a href="./INTERFACES.html">INTERFACES.md</a> - 按归属划分的 251 条命令面、 v1→v2 映射与 L1SVC 服务表（由树生成：<code>make api-docs</code>）</li><li><a href="./FAQ.html">FAQ.md</a> - 常见问题</li><li><a href="./CONTRIBUTING.html">CONTRIBUTING.md</a> - 基本规则与 PR 门槛</li><li>完整文档中心（用户手册、开发者手册、驱动上手指南、L1 扩展指南、 内部机制）：<strong><a href="https://cubestudio-dev.github.io/OpenCubeOS/docs/" target="_blank" rel="noreferrer">https://cubestudio-dev.github.io/OpenCubeOS/docs/</a></strong></li></ul><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p>以下数字全部在构建时由机器验证 （<code>make api-docs</code> 写入 <code>docs/data/*.json</code>；每项均附 README 验证命令）：</p><ul><li><strong>源代码</strong>：379 个文件共 130,572 行——core + arch + drivers + services + recovery + tui + chinese + boot + l1apps，含头文件， 排除 docs/tools/tests 与生成的数据块。验证： <code>git ls-files | grep -E &#39;\\.(c|h|S)$&#39; | grep -E &#39;^(core|arch|drivers|services|recovery|tui|chinese|boot|l1apps)/&#39; | grep -v &#39;^core/generated/&#39; | grep -vE &#39;userprogs_data|chinese_font_data|pinyin_data|grub_boot_data&#39; | xargs wc -l</code></li><li><strong>命令</strong>：共 251 条——L0 恢复 Shell 99 条（<code>oc&gt;</code> 提示符下 <code>help -a</code>）+ Ring-3 SYS_L1SVC 服务命令 133 条 + ush 内建 19 条。 v1.0.0 的每条命令都有映射——见 <a href="./INTERFACES.html">INTERFACES.md</a> 的 v1→v2 表（233 条基线全映射）。</li><li><strong>L1SVC 服务面</strong>：17 个类别 / 158 个编号操作——精确表格见 <a href="./INTERFACES.html">INTERFACES.md</a>。</li><li><strong>系统调用</strong>：54 个 - 验证：<code>grep -c &#39;#define SYS_&#39; core/core_syscall.h</code></li><li><strong>CI</strong>：每次 push 全绿——构建、ISO、打包、host 测试与可复现门 （<code>.github/workflows/build.yml</code>）。</li></ul><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>Apache 2.0（见 <a href="./LICENSE.html">LICENSE</a>）。版权所有 2026 cubestudio-dev &lt;cubestudio@qq.com&gt;。</p>`,24)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
